import{_ as t,o,c as s,aj as i}from"./framework.js";const p=JSON.parse('{"title":"k.site.runJob | Site | KScript API","description":"Site Scheduled Task (SiteJob) configures name, schedule and Inline KScript in the background. The runtime is executed on the server side by JobService without going through the frontend…","frontmatter":{"title":"k.site.runJob | Site | KScript API","description":"Site Scheduled Task (SiteJob) configures name, schedule and Inline KScript in the background. The runtime is executed on the server side by JobService without going through the frontend…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/api/site/job.html"}]]},"headers":[],"relativePath":"api/site/job.md","filePath":"en/api/site/job.md","lastUpdated":1783042246000}'),n={name:"api/site/job.md"};function a(d,e,r,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="k-site-runjob" tabindex="-1">k.site.runJob <a class="header-anchor" href="#k-site-runjob" aria-label="Permalink to &quot;k.site.runJob&quot;">​</a></h1><blockquote><p>Corresponding backend <a href="/kb-docs/cms/development/jobs.html">Develop -&gt; Scheduled Jobs</a></p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Site <strong>Scheduled Task (SiteJob)</strong> configures name, schedule and <strong>Inline KScript</strong> in the background. The runtime is executed on the server side by <code>JobService</code> without going through the frontend HTTP.</p><p>The script side only provides <strong>trigger</strong> and (some versions) <strong>status query</strong>; please complete the addition, deletion and modification of tasks in the background.</p><div class="tip custom-block"><p class="custom-block-title">configure the background first</p><p>After <strong>adding a task</strong> on <a href="/kb-docs/cms/development/jobs.html">Scheduled Jobs</a> and saving it, you can call <code>k.site.runJob</code> by <strong>name</strong> in other codes.</p></div><h2 id="k-site-runjob-name" tabindex="-1">k.site.runJob(name) <a class="header-anchor" href="#k-site-runjob-name" aria-label="Permalink to &quot;k.site.runJob(name)&quot;">​</a></h2><p>Execute the specified task asynchronously once (equivalent to list <strong>Run</strong>, the log description is <code>Manual trigger from kscript</code>).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>yes</td><td>Task <strong>name</strong> or task ID (GUID string)</td></tr></tbody></table><p><strong>Returns:</strong> <code>void</code>.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.site.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runJob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nightly_sync&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Throws <code>Job not found</code> if the task does not exist.</p><div class="warning custom-block"><p class="custom-block-title">Relationship with the scheduler</p><p><code>runJob</code> <strong>does not</strong> replace periodic scheduling; recurring tasks are still automatically executed according to the background <strong>start time</strong> and <strong>interval</strong>. Manual running can be used for debugging when the site is not published.</p></div><h2 id="execution-environment" tabindex="-1">execution environment <a class="header-anchor" href="#execution-environment" aria-label="Permalink to &quot;execution environment&quot;">​</a></h2><ul><li>Uses the current site&#39;s server-side execution context.</li><li>Code comes from <code>SiteJob.Code</code> field (backend Monaco save), executed with <strong>Module</strong> script type, <strong>Long Task</strong> option.</li><li>You can use the same <code>k.*</code> API as other server-side codes (<code>k.DB</code>, <code>k.content</code>, <code>k.mail</code>, etc.).</li></ul><p>The execution results are written to the center <strong>JobLog</strong> (background <strong>Completed</strong> / <strong>Failed</strong> tab).</p><h2 id="difference-from-k-site-codes" tabindex="-1">Difference from k.site.codes <a class="header-anchor" href="#difference-from-k-site-codes" aria-label="Permalink to &quot;Difference from k.site.codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>SiteJob (scheduled task)</strong></th><th><strong>k.site.codes</strong></th></tr></thead><tbody><tr><td>Configuration</td><td>Development → Scheduled tasks</td><td>Development → Code</td></tr><tr><td>trigger</td><td>Scheduler / <code>runJob</code></td><td>HTTP routing, events, page references</td></tr><tr><td>code storage</td><td><code>SiteJob.Code</code> inline</td><td><code>Code</code> Resources <code>body</code></td></tr></tbody></table><p>If you want to reuse the same piece of logic, you can place the public function in Code and call it by convention in the task script (you need to add <code>import</code> yourself or inline it. Kooboo tasks do not automatically bind Code Id by default).</p><h2 id="module-tasks" tabindex="-1">Module tasks <a class="header-anchor" href="#module-tasks" aria-label="Permalink to &quot;Module tasks&quot;">​</a></h2><p>The <strong>task</strong> and events of <code>module.config</code> in the module package are handled by <code>k.module</code> / module scheduling, not <code>k.site.runJob</code>. See <a href="/kb-docs/api/module/">k.module</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/kb-docs/cms/development/jobs.html">Scheduled Jobs（CMS）</a></li><li><a href="./">k.site</a></li><li><a href="./code.html">k.site.codes</a></li></ul>',23)])])}const g=t(n,[["render",a]]);export{p as __pageData,g as default};
